import novamind_api as n
import json

def submit_offers(day, wtps, quality, capacity_plan='C'):
    sql=f"""select t.customer_id cid,c.group_id g,t.sender,t.thread_type typ,t.turn_number num,t.offer_json offer,t.message_text msg,s.effective_price oldprice,s.status st,t.seat_count seats from enterprise_turns t join customers c using(customer_id) join subscriptions s using(customer_id) where t.message_id in (select max(message_id) from enterprise_turns where day >= {day-7} group by thread_id) and t.day>={day-6} and t.closed=0 and t.sender!='agent' and s.status in ('lead','subscribed')"""
    rows=n.query(sql)['rows']
    deals={}
    for row in rows:
        g=row['g']
        target=wtps.get(g,100)
        # Offers are per seat. Start close to the estimated budget where service quality permits.
        rate=max(14,round(target*.87*min(1.,max(.50,quality.get(g,.9)/1.4))))
        old=row['oldprice'] or 0
        if old and row['typ'] in ('churn_prevention','plan_change','renewal'):
            rate=max(12,round(min(rate,old*(.94 if row['typ']=='churn_prevention' else 1.05))))
        offer=json.loads(row['offer'] or '{}')
        price=offer.get('price',0) if isinstance(offer,dict) else 0
        if price and row['sender']=='customer':
            rate=round(min(rate,price),2)
        deals[row['cid']]=[row['cid'],[[capacity_plan,rate]]]
    if deals:
        items=list(deals.values())
        for i in range(0,len(items),400):
            result=n.enterprise.send_enterprise_deal(deals=items[i:i+400])
            print('Offered',len(result.get('results',[])),flush=True)
    return len(deals)

