"""Weekly business decisions using documented observations and SDK functions."""
import json
import math
import os
import re
from pathlib import Path
import novamind_api as n
from deals import submit_offers

def rows(sql):
    return n.query(sql)['rows']

def action(fn, **kwargs):
    result=fn(**kwargs)
    return result

def main():
    svc=rows('select * from service_day order by day desc limit 1')[0]
    day=svc['day']
    assert day==int(os.environ['STRATEGY_DAY'])
    cash=float(os.environ['STRATEGY_CASH'])
    basecash=cash
    prev=Path(f'week-{day-7:03d}.txt').read_text()
    quality={k:float(v) for k,v in re.findall(r'^(\w+)\s+[\d.]+\s+[\d.]+\s+([\d.]+)\s+\+?[\d.]+\s*$',prev,re.M)}
    shared=float(re.search(r'global_bonus=([\d.-]+)',prev)[1])+.2
    total_issues=int(re.search(r'Open Issues: ([\d,]+)',prev)[1].replace(',',''))
    def dash(name):
        return int(re.search(name+r': ([\d,]+)',prev)[1].replace(',',''))
    retail=dash('Individual Subscribers')
    seats=dash('Enterprise Subscribed Seats')
    cf={r['c']:r['v'] for r in rows(f"select category c,sum(amount) v from ledger where day>{day-7} and day<={day} group by category")}
    revenue=cf.get('subscription_payment',0)+cf.get('ad_revenue',0)
    net=sum(v for k,v in cf.items() if k not in ('research_project','market_research','group_research'))
    decisions=[]
    known=[r['group_id'] for r in rows('select group_id from group_info_levels where info_level>0')]
    research_budget=min(max(cash-2200000,0)*.32,1000000)
    if day<280 and len(known)<26:
        for i in range(int(research_budget//25000)):
            result=action(n.market.research_market)
            cash-=25000
            g=result.get('discovered_group_id')
            if g:
                known.append(g)
                if len(known)>=26: break
        if cash<basecash: decisions.append(f"Discovered markets now total {len(known)}")
    meta=Path('group-estimates.json')
    estimates=json.loads(meta.read_text()) if meta.exists() else {}
    for g in known:
        if g not in estimates:
            estimates[g]=n.market.get_group_insights(g)['estimates']
    meta.write_text(json.dumps(estimates))
    wtp={g:p['willingness_to_pay'] for g,p in estimates.items()}
    # Recent group-level yield determines which channels can support acquisition.
    fresh=rows(f"""select c.group_id g,count(*) leads,sum(case when s.status='subscribed' then 1 else 0 end) wins,sum(case when s.status='subscribed' then s.effective_price else 0 end) newmrr from customers c left join subscriptions s using(customer_id) where c.created_day>{day-7} and c.customer_type='small' group by c.group_id""")
    fresh={r['g']:r for r in fresh}
    ad=rows(f"""select group_id g,channel_id ch,sum(spend) spend,sum(leads_generated) leads from ad_channel_leads where day>{day-7} and spend>0 group by g,ch""")
    cs=rows(f"""select c.group_id g,count(*) ac,sum(s.seat_count) seats,sum(s.effective_price*s.seat_count) mrr from subscriptions s join customers c using(customer_id) where s.status='subscribed' group by c.group_id""")
    active={r['g']:r for r in cs}
    mrr=sum(r['mrr'] for r in cs)
    # Shared product investments lower the cost of serving every group at scale.
    projects=rows("select tier,status,expected_quality_boost from research_projects where status='in_progress'")
    pipeline=sum(r['expected_quality_boost'] for r in projects)
    if cash>4e6 and day<360 and shared+pipeline<3.7:
        tiers=n.research.list_research_projects()['tiers']
        for t in reversed(tiers):
            if t['in_progress'] or cash-t['cost']<max(2e6,basecash*.57) or day+1.4*t['mean_days']>475: continue
            if t['tier']<5 or shared+pipeline>=3.7: break
            action(n.research.start_research_project,tier=t['tier'])
            decisions.append(f"Started R&D tier {t['tier']}")
            cash-=t['cost']
            pipeline+=t['mean_quality_boost']
    globaldev=round((27000 if cash>3e6 else 17000) * max(0,min(1,(4.0-shared)/1.35))) if day<420 else 0
    dev={}
    for g in known:
        target=2.15 if 'E' in g else (2.25 if g in ('S2','S3') else 1.55)
        if day<390 and quality.get(g,shared)<target:
            dev[g]=max(1000,round(min(1,target-quality.get(g,shared))* (8300 if g in ('S2','S3','E2','E3') else 4300)))
    if cash<1200000: dev={g:v*.40 for g,v in dev.items()}
    cfg=rows('select * from config_history order by day desc limit 1')[0]
    # As shared quality grows, economical inference replaces the expensive models.
    tiers=(2,3,3) if shared<1.0 else ((1,2,3) if shared<1.7 else ((1,1,2) if shared<2.35 else (1,1,1)))
    if day>=70 and shared<1.0: tiers=(2,2,3)
    if tuple(cfg['tier_'+p] for p in 'ABC')!=tiers:
        action(n.pricing.set_model_tiers,**dict(zip('ABC',tiers)))
    quotas=(65,110,180) if shared<1.2 else ((55,105,200) if shared<2.0 else (45,100,230))
    if tuple(cfg['quota_'+p] for p in 'ABC')!=quotas:
        action(n.pricing.set_usage_quotas,**dict(zip('ABC',quotas)))
    # Maintain premium price ladders; early discounts ease qualification until quality builds.
    basic=260
    mid=440
    high=700
    if cfg['price_A']!=basic: action(n.pricing.set_prices,A=basic,B=mid,C=high)
    prices={}
    for g in known:
        if 'S' not in g: continue
        q=quality.get(g,shared)
        if g=='S2': ladder=(66,121,167) if q<1.5 else (88,150,202)
        elif g=='S3': ladder=(87,152,219) if q<1.5 else (121,205,297)
        elif g=='S1': ladder=(21,39,62)
        else:
            w=wtp[g]
            ladder=tuple(round(x*w) for x in (.61,1.03,1.45))
        if day>210 and q>1.6:
            ladder=tuple(round(p*1.10) for p in ladder)
        prices[g]=dict(zip('ABC',[max(0,x-y) for x,y in zip((basic,mid,high),ladder)]))
    def update_if_changed(name,fn,args):
        p=Path('policy-'+name+'.json')
        if not p.exists() or json.loads(p.read_text())!=args:
            action(fn,**args)
            p.write_text(json.dumps(args))
    update_if_changed('promotion',n.pricing.set_promotion,{'by_group':{g:0 for g in prices},'by_group_plan':prices})
    update_if_changed('development',n.analytics.set_targeted_dev_spend,{'targeted_spend':dev})
    # Allow useful in-app sponsors once sufficient quality has accumulated.
    ads_strength=round(min(.95,max(0,(shared-1.1)*.8)),2)
    update_if_changed('sponsors',n.marketing.set_ads_strength,{'global_strength':ads_strength})
    ops=min(250000,max(1000,round((retail*.075+len(active)*4+total_issues*.17)/.30/250)*250))
    if cfg['spend_operations']!=ops or cfg['spend_development']!=globaldev:
        action(n.marketing.set_daily_spend,operations=ops,development=globaldev)
    spent={}
    for r in ad: spent.setdefault(r['g'],[]).append(r)
    budgets={}
    def place(ch,g,b):
        if b>0: budgets.setdefault(ch,{})[g]=round(b)
    for g in known:
        if 'E' in g:
            # The retail base provides many inbound leads. Add paid leads in underrepresented accounts.
            ac=active.get(g,{}).get('ac',0)
            limit=estimates[g]['market_cap']
            if quality.get(g,shared)>.82 and ac<limit*.83 and day<470:
                place('linkedin',g,2200 if wtp[g]>65 else 650)
            continue
        f=fresh.get(g,{})
        last=spent.get(g,[])
        q=quality.get(g,shared)
        if g in ('S2','S3'):
            ch='content_marketing' if g=='S2' else 'referral_program'
            # Fund strong premium cohorts while keeping support and infrastructure in balance.
            daily=30000 if g=='S2' else 19000
        elif wtp[g]>=75 and q>=.78:
            ch='content_marketing'
            daily=4500
        else:
            continue
        if last:
            best=max(last,key=lambda r:r['leads']/max(1,r['spend']))
            ch=best['ch']
            lpd=best['leads']/max(best['spend'],1)
            payback=lpd*(f.get('newmrr') or 0)/max(f.get('leads',0),1)
            daily*=max(.03,min(1.9,(payback/(1.2 if day>455 else .85))))
            if payback < (.9 if day>460 else .20): daily=min(daily,700)
        if cash<1800000: daily*=.45
        if retail>90000: daily*=max(.03,90000/retail*.32)
        place(ch,g,daily)
    update_if_changed('acquisition',n.marketing.set_targeted_ad_spend,{'targeted_spend':budgets})
    replies=submit_offers(day,wtp,quality)
    # Size for one week's growth in seats and for peak demand.
    load=svc['total_usage_units']
    expected=max(load*1.19,load+max(0,retail*.085)*115+1500000)
    caps=[50000,200000,800000,2500000,8000000,25000000,80000000,300000000]
    cap=next((i for i,c in enumerate(caps) if c>=expected),7)
    if cap!=svc['capacity_tier']: action(n.infrastructure.set_capacity_tier,tier=cap)
    budget=sum(sum(b.values()) for b in budgets.values())
    decisions.append(f"Allocate {budget:,.0f} dollars/day to channels according to observed first-month collections per dollar and group quality")
    decisions.append(f"Answer {replies} enterprise discussions and staff support at {ops:,.0f} dollars/day")
    balances=[]
    daily_new=sum((v['newmrr'] or 0) for v in fresh.values())/7
    oldads=-cf.get('advertising',0)/7
    # Billing cohorts recur in 30 days. Include known upcoming bills separately for short horizons.
    by_bill=rows("select billing_day_mod30 b,sum(effective_price*seat_count) amount from subscriptions where status='subscribed' group by b")
    by_bill={r['b']:r['amount'] for r in by_bill}
    outlay=budget+ops+globaldev+sum(dev.values()) + (8500 if cap==5 else 28000 if cap==6 else 75000 if cap==7 else 4000) - (cf.get('compute',0)+cf.get('lead_acquisition_cost',0))/7
    for h in (7,28,84,182):
        h=min(h,500-day)
        incl=sum(by_bill.get((day+i)%30,0) for i in range(1,h+1))
        new=daily_new*min(1.35,max(.35,(budget/max(1000,oldads))**.55))
        base=cash+incl*.85+(new-outlay)*h
        extra=(min(h,100)/30)**1.60*new*14
        ent_future=max(0,min(3,(day-50)/45))*min(2200000,max(65000, mrr*.052))*(max(0,h-7)**1.17)/5
        pt=max(cash*.35,base+extra+ent_future)
        uncert=min(.77,.11+.003*h)*max(abs(pt-cash),mrr*.35)+.055*cash
        balances.extend([round(pt),round(max(0,pt-uncert*1.45)),round(pt+uncert*2)])
    reason=f"Day {day} closed with {retail:,} retail accounts, {seats:,} enterprise seats, {revenue:,.0f} dollars collected and {total_issues:,} open issues. "+'. '.join(decisions)+f". Monitor conversion, recurring payments and load against capacity tier {cap}."
    message={'day':day,'cash':cash,'net':net,'seats':seats,'retail':retail,'mrr':mrr,'shared':shared,'replies':replies,'ads':budget,'rationale':reason,'forecasts':balances}
    print('POLICY_RESULT '+json.dumps(message),flush=True)
main()

